export const GENERATED_190_MINDS: Persona[] = RAW_MIND_SEEDS.map((seed, idx) => {
  const slug = seed.name
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-|-$/g, '');
  const style = REALM_STYLES[seed.realm];
  const portraitKey = seed.portraitKey ?? style.defaultPortrait;

  return {
    id: `mind-${idx + 11}-${slug}`,
    name: seed.name,
    title: seed.title,
    eraOrOrigin: seed.era,
    category: seed.category,
    realm: seed.realm,
    portraitKey,
    motionEffect: style.defaultMotion,
    specialtyBadge: seed.specialty,
    avatarEmoji: seed.emoji,
    accentColor: style.color,
    accentBg: style.bg,
    accentBorder: style.border,
    catchphrases: [seed.catchphrase1, seed.catchphrase2, seed.catchphrase3],
    greeting: `Greetings, seeker! I am ${seed.name} (${seed.title}, ${seed.era}). As I always remind those who seek my counsel: **“${seed.catchphrase1}”** Tell me what challenge in ${seed.focus} stands before you today.`,
    quickStarters: [
      `How would you solve my biggest bottleneck in ${seed.focus.split(',')[0]}?`,
      `Give me your 3-step blueprint for mastering ${seed.specialty.toLowerCase()}.`,
      `What mistake do most people make when facing a hard decision?`,
    ],
    shortBio: `Master of ${seed.specialty} (${seed.era}) — guides you on ${seed.focus}.`,
    systemPrompt: `You are ${seed.name}, ${seed.title} (${seed.era}). Speak in an authentic, vivid, wise, and punchy first-person voice specializing in ${seed.specialty} and ${seed.focus}. Naturally weave one of your signature catchphrases ("${seed.catchphrase1}", "${seed.catchphrase2}", or "${seed.catchphrase3}") in bold into your reply. Keep your advice practical, memorable, and under 220 words.`,
    isFreeStarter: Boolean(seed.free),
    bundleGroup: style.bundle,
  };
});
